/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        if (!head || k == 1) return head;

        // Dummy node
        ListNode dummy(0);
        dummy.next = head;
        ListNode* prev = &dummy, *curr = head, *next = nullptr;

        // Count total number of nodes
        int count = 0;
        while (curr) {
            count++;
            curr = curr->next;
        }

        // Reverse nodes in k groups
        curr = head;
        while (count >= k) {
            next = curr->next;
            for (int i = 1; i < k; i++) {
                curr->next = next->next;
                next->next = prev->next;
                prev->next = next;
                next = curr->next;
            }
            prev = curr;
            curr = next;
            count -= k;
        }

        return dummy.next;
    }
};
